f=Path("corpus/lessons/round-31.md"); text=f.read_text(); items=[(text.count("\n",0,m.start())+1,m.group()) for m in re.finditer(r"(?ms)^- .*?(?=^- |\Z)",text)]; claims=[(n+body[:body.find("killed by the counter")].count("\n"),body) for n,body in items if "fail-open hashing (MutC2Hash)" in body and "killed by the counter" in body]; paths=sorted(Path(".ufo/waves/round-31/falsify/MutC2Hash").glob("failopen.mutated.*.receipt.json")); receipts=[json.loads(p.read_text()) for p in paths]; missing=bool(claims) and (not paths or any(p.name not in body for _,body in claims for p in paths)); over=bool(claims) and any(r["matched"]>=r["total"] for r in receipts); bad=missing or over; shown=", ".join(p.name+"="+str(r["matched"])+"/"+str(r["total"]) for p,r in zip(paths,receipts)); print(("FAIL" if bad else "PASS")+": "+("round-31.md:"+",".join(str(n) for n,_ in claims)+" calls fail-open counter-killed; "+("receipt citations missing; " if missing else "")+("all-match receipts: " if over else "")+shown if bad else "kill claims cite below-total receipts")); sys.exit(1 if bad else 0)
